import React, { useState } from 'react';
import { useData } from './DataContext'; // Importar o hook useData correto

function Cadastro() {
  const { addData } = useData(); // Desestruturar addData do contexto
  const [nomeCompleto, setNomeCompleto] = useState('');
  const [dataNascimento, setDataNascimento] = useState('');
  const [telefone, setTelefone] = useState('');

  const handleSubmit = (event) => {
    event.preventDefault();
    const newData = { nomeCompleto, dataNascimento, telefone };
    addData(newData); // Adiciona os dados ao contexto
    // Limpar os campos ou adicionar outras lógicas
  };

  return (
    <div>
      <h1>Cadastro</h1>
      <form onSubmit={handleSubmit}>
        <label>
          Nome Completo:
          <input type="text" value={nomeCompleto} onChange={(e) => setNomeCompleto(e.target.value)} />
        </label>
        <br />
        <label>
          Data de Nascimento:
          <input type="date" value={dataNascimento} onChange={(e) => setDataNascimento(e.target.value)} />
        </label>
        <br />
        <label>
          Telefone:
          <input type="text" value={telefone} onChange={(e) => setTelefone(e.target.value)} />
        </label>
        <br />
        <button type="submit">Cadastrar</button>
      </form>
    </div>
  );
}

export default Cadastro;
